/*! PixelPlayer Build 88 combined COI + PWA service worker. Based on coi-serviceworker v0.1.7 (MIT). */
let coepCredentialless=false;
const PP_CACHE='pixelplayer-shell-v88';
const PP_SHELL=['./','./index.html','./offline.html','./manifest.webmanifest','./dashboard.css','./system-art.css','./nav.css','./nav.js','./pwa.js','./dashboard.js','./dashboard-library.js','./system-icons.js','./emulator.css','./emulator-session.js','./system-shell.js','./system-emulator.js','./emulator-tabs.js','./folder-indexer-upgrade.js','./boxart-progress.js','./icons/pixelplayer-icon.svg','./icons/pixelplayer-maskable.svg'];
function withIsolation(response){
  if(!response||response.status===0)return response;
  const h=new Headers(response.headers);
  h.set('Cross-Origin-Embedder-Policy',coepCredentialless?'credentialless':'require-corp');
  if(!coepCredentialless)h.set('Cross-Origin-Resource-Policy','cross-origin');
  h.set('Cross-Origin-Opener-Policy','same-origin');
  return new Response(response.body,{status:response.status,statusText:response.statusText,headers:h});
}
if(typeof window==='undefined'){
  self.addEventListener('install',event=>event.waitUntil((async()=>{
    self.skipWaiting();
    const cache=await caches.open(PP_CACHE);
    await Promise.allSettled(PP_SHELL.map(async url=>{try{const r=await fetch(new Request(url,{cache:'reload'}));if(r.ok)await cache.put(url,r.clone())}catch{}}));
  })()));
  self.addEventListener('activate',event=>event.waitUntil((async()=>{
    const keys=await caches.keys();
    await Promise.all(keys.filter(k=>k.startsWith('pixelplayer-shell-')&&k!==PP_CACHE).map(k=>caches.delete(k)));
    await self.clients.claim();
  })()));
  self.addEventListener('message',event=>{
    if(!event.data)return;
    if(event.data.type==='deregister')self.registration.unregister().then(()=>self.clients.matchAll()).then(cs=>cs.forEach(c=>c.navigate(c.url)));
    else if(event.data.type==='coepCredentialless')coepCredentialless=event.data.value;
    else if(event.data.type==='skipWaiting')self.skipWaiting();
  });
  self.addEventListener('fetch',event=>{
    const original=event.request;
    if(original.method!=='GET')return;
    if(original.cache==='only-if-cached'&&original.mode!=='same-origin')return;
    const url=new URL(original.url);
    const same=url.origin===self.location.origin;
    const req=coepCredentialless&&original.mode==='no-cors'?new Request(original,{credentials:'omit'}):original;
    event.respondWith((async()=>{
      if(!same){try{return withIsolation(await fetch(req))}catch{return fetch(req)}}
      const cache=await caches.open(PP_CACHE);
      try{
        const fresh=await fetch(new Request(req,{cache:'no-cache'}));
        if(fresh&&fresh.ok&&(original.mode==='navigate'||['script','style','image','font','manifest'].includes(original.destination)))cache.put(original,fresh.clone()).catch(()=>{});
        return withIsolation(fresh);
      }catch{
        let cached=await cache.match(original,{ignoreSearch:true});
        if(!cached&&original.mode==='navigate')cached=await cache.match('./offline.html');
        if(cached)return withIsolation(cached);
        throw new Error('PixelPlayer offline resource unavailable');
      }
    })());
  });
}else{
  (()=>{
    const prior=sessionStorage.getItem('coiReloadedBySelf');sessionStorage.removeItem('coiReloadedBySelf');
    const degraded=prior==='coepdegrade';
    const cfg={shouldRegister:()=>true,shouldDeregister:()=>false,coepCredentialless:()=>true,coepDegrade:()=>true,doReload:()=>location.reload(),quiet:true,...window.coi};
    const sw=navigator.serviceWorker&&navigator.serviceWorker.controller;
    if(sw&&!window.crossOriginIsolated)sessionStorage.setItem('coiCoepHasFailed','true');
    const failed=sessionStorage.getItem('coiCoepHasFailed');
    if(sw){
      const degrade=cfg.coepDegrade()&&!(degraded||window.crossOriginIsolated);
      sw.postMessage({type:'coepCredentialless',value:!(degrade||failed&&cfg.coepDegrade())&&cfg.coepCredentialless()});
      if(degrade){sessionStorage.setItem('coiReloadedBySelf','coepdegrade');cfg.doReload('coepdegrade')}
      if(cfg.shouldDeregister())sw.postMessage({type:'deregister'});
    }
    if(cfg.shouldRegister()&&window.isSecureContext&&navigator.serviceWorker){
      navigator.serviceWorker.register(document.currentScript?.src||'coi-serviceworker.min.js?v=88',{scope:'./'}).then(reg=>{
        reg.addEventListener('updatefound',()=>{});
        if(reg.active&&!navigator.serviceWorker.controller){sessionStorage.setItem('coiReloadedBySelf','notcontrolling');cfg.doReload('notcontrolling')}
      }).catch(e=>{if(!cfg.quiet)console.error('PixelPlayer service worker registration failed',e)});
    }
  })();
}